use std::collections::VecDeque;

struct RetryQueue {
    pending: VecDeque<Vec<u8>>,
    max_capacity: usize,
}

impl RetryQueue {
    fn push_failed(&mut self, request: Vec<u8>) {
        if self.pending.len() >= self.max_capacity {
            self.pending.pop_front(); // Evict oldest
        }
        self.pending.push_back(request);
    }
}
